<script setup lang="ts">
import { ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import StoryPlayer from "~/components/account/version-summary/StoryPlayer.vue";
import { normalizeAnnualSummary } from "~/utils/annualSummary";
defineI18nRoute(false); definePageMeta({ layout: "admin-taiko", middleware: "admin-auth" }); useHead({ title: "年度报告" });
const apiFetch = useAdminApiFetch(); const query = ref(""); const loading = ref(false); const items = ref<any[]>([]); const preview = ref<any>(null); const previewStarted = ref(false); const { t } = useI18n();
const previewSummary = computed(() => preview.value ? normalizeAnnualSummary(preview.value, "zh", (key, params) => t(key, params || {})) : null);
const search = async () => { loading.value = true; try { items.value = (await apiFetch<{ items: any[] }>("/api/admin/annual-summaries", { query: { q: query.value } })).items; } catch (e:any) { ElMessage.error(e?.data?.statusMessage || "查询失败"); } finally { loading.value = false; } };
const build = async (item:any, force=false) => { try { if (item.hasViewerAccount) { await apiFetch("/api/admin/annual-summaries/build", { method: "POST", body: { userId: item.userId, bindingId: item.bindingId, force } }); ElMessage.success("年度报告生成任务已提交，请稍后刷新"); } else { const result = await apiFetch<{summary:any}>("/api/admin/annual-summaries/build", { method: "POST", body: { taikoId: item.taikoId } }); preview.value = result.summary; previewStarted.value = false; } } catch (e:any) { ElMessage.error(e?.data?.statusMessage || "生成失败"); } };
</script>
<template><div class="admin-page-stack"><div class="page-heading"><div><span class="eyebrow">Annual reports</span><h2>年度报告管理</h2><p>扫描全部 userdata，按鼓众 ID、真实昵称或用户名模糊匹配；无 Viewer 账号的数据也可生成预览。</p></div></div><el-card><div class="search"><el-input v-model="query" placeholder="输入鼓众 ID、昵称或用户名" clearable @keyup.enter="search" /><el-button type="primary" :loading="loading" @click="search">查询</el-button></div><el-table v-if="items.length" :data="items" stripe><el-table-column prop="nickname" label="昵称"/><el-table-column prop="username" label="用户名"/><el-table-column prop="taikoId" label="鼓众 ID"/><el-table-column label="状态"><template #default="{row}">{{ row.hasViewerAccount ? '可持久化' : '仅预览' }}</template></el-table-column><el-table-column label="操作" width="220"><template #default="{ row }"><el-button link type="primary" @click="build(row)">{{ row.hasViewerAccount ? '生成/查看' : '生成预览' }}</el-button><el-button v-if="row.hasViewerAccount" link type="warning" @click="build(row,true)">强制重建</el-button></template></el-table-column></el-table><el-empty v-else description="暂无结果" /></el-card><div v-if="previewSummary" class="preview"><button class="preview__close" @click="preview=null">关闭预览</button><StoryPlayer :summary="previewSummary" :started="previewStarted" @start="previewStarted=true" @open-drawer="preview=null" /></div></div></template>
<style scoped>.admin-page-stack{display:grid;gap:20px}.page-heading h2{margin:6px 0;font-size:30px}.page-heading p{margin:0;color:#6b7280}.eyebrow{color:#8f6d3f;font-size:12px;letter-spacing:.14em;text-transform:uppercase}.search{display:flex;gap:10px;margin-bottom:18px}.search .el-input{max-width:420px}</style>
